mapper.select:
select MST_SHARE_PRICE.SHARES_ID as finprodId, MST_SHARE_PRICE.CLOSE_PRICE as marketPrice, null as sduration, null as interestDuration, null as mduration, null as sevenDayYearYield, MST_SHARE_PRICE.DEAL_DATE as quotationDate, null as valueSource, null as dirtyPrice, null as marketPriceDuration from MST_SHARE_PRICE where 1=1
and MST_SHARE_PRICE.SHARES_ID in
#{item}
AND MST_SHARE_PRICE.DEAL_DATE = to_date(#{paramDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')
union all select MST_BOND_VALUATION_INFO.SEC_ID as finprodId, MST_BOND_VALUATION_INFO.NETPRICE as marketPrice, MST_BOND_VALUATION_INFO.SDURATION as sduration, MST_BOND_VALUATION_INFO.INTEREST_DURATION as interestDuration, MST_BOND_VALUATION_INFO.MDURATION as mduration, null as sevenDayYearYield, MST_BOND_VALUATION_INFO.VALUE_DATE as quotationDate, MST_BOND_VALUATION_INFO.VALUE_SOURCE as valueSource, MST_BOND_VALUATION_INFO.PRICE as dirtyPrice, MST_BOND_VALUATION_INFO.M_DURATION as marketPriceDuration from MST_BOND_VALUATION_INFO left join fin_product on fin_product.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID where 1=1
and fin_product.FINPROD_ID in
#{item}
/** modify 债券行情信息取值最近五个工作日内的最新数据 **/ AND (MST_BOND_VALUATION_INFO.SEC_ID,MST_BOND_VALUATION_INFO.VALUE_DATE) in ( select MST_BOND_VALUATION_INFO.SEC_ID,max(MST_BOND_VALUATION_INFO.VALUE_DATE) from MST_BOND_VALUATION_INFO left join fin_product on fin_product.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID where (fin_product.calendar_id,MST_BOND_VALUATION_INFO.Value_Date) in (SELECT calendar_id,cdate FROM (SELECT calendar_id, cdate, ROW_NUMBER() OVER(PARTITION BY calendar_id ORDER BY cdate desc) AS RN FROM mst_holiday where cdate <=to_date(#{paramDate,jdbcType=VARCHAR}, 'yyyy-MM-dd') and is_holiday = 0)WHERE RN <= 5) and MST_BOND_VALUATION_INFO.VALUE_SOURCE = DECODE(fin_product.TRADE_MARKET, '01', 'CBC', '03', 'CSD', '04', 'CSD')
and fin_product.FINPROD_ID in
#{item}
group by MST_BOND_VALUATION_INFO.SEC_ID )
AND (MST_BOND_VALUATION_INFO.SEC_ID,MST_BOND_VALUATION_INFO.VALUE_DATE) in (select T.SEC_ID,max(T.VALUE_DATE) from MST_BOND_VALUATION_INFO T left join fin_product on fin_product.FINPROD_MARKET_ID = T.SEC_ID where 1=1
and fin_product.FINPROD_ID in
#{item}
and T.VALUE_DATE <= to_date(#{paramDate,jdbcType=VARCHAR}, 'yyyy-MM-dd') and T.VALUE_SOURCE = DECODE(fin_product.TRADE_MARKET, '01', 'CBC', '03', 'CSD', '04', 'CSD') group by T.SEC_ID)
and MST_BOND_VALUATION_INFO.VALUE_SOURCE = DECODE(fin_product.TRADE_MARKET, '01', 'CBC', '03', 'CSD', '04', 'CSD') union all select FIN_PRODUCT_VALUATION.FINPROD_ID as finprodId, FIN_PRODUCT_VALUATION.VALUATION as marketPrice, null as sduration, null as interestDuration, null as mduration, FIN_PRODUCT_VALUATION.DAY7_YEAR_YIELD as sevenDayYearYield, FIN_PRODUCT_VALUATION.VAL_DATE as quotationDate, null as valueSource, null as dirtyPrice, null as marketPriceDuration from FIN_PRODUCT_VALUATION left join fin_product on fin_product.FINPROD_MARKET_ID = FIN_PRODUCT_VALUATION.FINPROD_ID where 1=1
and fin_product.FINPROD_ID in
#{item}
and FIN_PRODUCT_VALUATION.VAL_DATE = (select max(T2.VAL_DATE) from FIN_PRODUCT_VALUATION T2 where T2.FINPROD_ID = FIN_PRODUCT_VALUATION.FINPROD_ID and T2.VAL_DATE = FIN_PRODUCT_VALUATION.VAL_DATE
AND T2.VAL_DATE <= to_date(#{paramDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')
) union all select MST_VAL_IRS.FINPROD_ID2 as finprodId, MST_VAL_IRS.VALUATION as marketPrice, null as sduration, null as interestDuration, null as mduration, null as sevenDayYearYield, MST_VAL_IRS.VAL_DATE as quotationDate, null as valueSource, null as dirtyPrice, null as marketPriceDuration from MST_VAL_IRS where 1=1
and MST_VAL_IRS.FINPROD_ID2 in
#{item}
AND MST_VAL_IRS.VAL_DATE = to_date(#{paramDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')
union all select MST_VAL_FX.FINPROD_ID2 as finprodId, MST_VAL_FX.VALUATION as marketPrice, null as sduration, null as interestDuration, null as mduration, null as sevenDayYearYield, MST_VAL_FX.VAL_DATE as quotationDate, null as valueSource, null as dirtyPrice, null as marketPriceDuration from MST_VAL_FX where 1=1
and MST_VAL_FX.FINPROD_ID2 in
#{item}
AND MST_VAL_FX.VAL_DATE = to_date(#{paramDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')
union all select MST_VAL_OP.FINPROD_ID2 as finprodId, MST_VAL_OP.VALUATION as marketPrice, null as sduration, null as interestDuration, null as mduration, null as sevenDayYearYield, MST_VAL_OP.VAL_DATE as quotationDate, null as valueSource, null as dirtyPrice, null as marketPriceDuration from MST_VAL_OP where 1=1
and MST_VAL_OP.FINPROD_ID2 in
#{item}
AND MST_VAL_OP.VAL_DATE = to_date(#{paramDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')

select MST_EXCHARGE_QUOTE.BASIS_CYY as basisCyy, MST_EXCHARGE_QUOTE.QUOT_CYY as quotCyy, MST_EXCHARGE_QUOTE.QUOT_UNIT as quotUnit, MST_EXCHARGE_QUOTE.MID_PRICE as price from MST_EXCHARGE_QUOTE where 1=1
and (MST_EXCHARGE_QUOTE.QUOT_CYY in
#{item,jdbcType=VARCHAR}
or MST_EXCHARGE_QUOTE.BASIS_CYY in
#{item,jdbcType=VARCHAR}
)
and MST_EXCHARGE_QUOTE.TRADE_DATE = (select max(T2.TRADE_DATE) from MST_EXCHARGE_QUOTE T2 where T2.BASIS_CYY = MST_EXCHARGE_QUOTE.BASIS_CYY and T2.QUOT_CYY = MST_EXCHARGE_QUOTE.QUOT_CYY
AND T2.TRADE_DATE <= to_date(#{paramDate,jdbcType=VARCHAR}, 'yyyy-MM-dd') )
AND MST_EXCHARGE_QUOTE.DATASOURCE_TYPE = #{datasourceType}
and MST_EXCHARGE_QUOTE.DATASOURCE_TYPE = 'CFETS'

select count(1) from
	(

		dual


	select sec_id from MST_BOND_VALUATION_INFO where sec_id = #{finprodid,jdbcType=VARCHAR}
	and value_date between to_date(#{startDate,jdbcType=VARCHAR}, 'yyyy-MM-dd') and to_date(#{endDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')
	union all
	select sec_id from MST_BOND_MARKET_INFO where sec_id = #{finprodid,jdbcType=VARCHAR}
	and value_date between to_date(#{startDate,jdbcType=VARCHAR}, 'yyyy-MM-dd') and to_date(#{endDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')


		select FUND_CODE from MST_FUND_MARKET_INFO where FUND_CODE = #{finprodid,jdbcType=VARCHAR}
		and value_date between to_date(#{startDate,jdbcType=VARCHAR}, 'yyyy-MM-dd') and to_date(#{endDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')


	select shares_id from MST_SHARE_PRICE where shares_id = #{finprodid,jdbcType=VARCHAR}
	and deal_date between to_date(#{startDate,jdbcType=VARCHAR}, 'yyyy-MM-dd') and to_date(#{endDate,jdbcType=VARCHAR}, 'yyyy-MM-dd')

	)
